INSERT INTO {schema}.axdirectsql (axdirectsqlid, cancel, sourceid, mapname, username, modifiedon, createdby, createdon, wkid, app_level, app_desc, app_slevel, cancelremarks, wfroles, sqlname, ddldatatype, sqlsrc, sqlsrccnd, sqltext, paramcal, sqlparams, accessstring, groupname, sqlquerycols, cachedata, cacheinterval, encryptedflds, adsdesc, smartlistcnd, pagination, applydimensions) VALUES ($q1864$1339770000000$q1864$, $q1865$F$q1865$, $q1866$0$q1866$, NULL, $q1867$admin$q1867$, $q1868$2026-06-23 13:21:29$q1868$, $q1869$admin$q1869$, $q1870$2026-06-23 13:21:29$q1870$, NULL, $q1871$1$q1871$, $q1872$1$q1872$, NULL, NULL, NULL, $q1873$ds_custom_useraccess$q1873$, NULL, $q1874$For developers$q1874$, $q1875$2$q1875$, $q1876$select * from 
(SELECT a2.username,
    a3.groupname,
    a5.rname,
    a5.sname,
    a5.stype,
        CASE a5.stype
            WHEN 't' THEN t.caption
            WHEN 'i' THEN i.caption
            WHEN 'p' THEN p.caption
            ELSE NULL 
        END AS caption
   FROM axusergroups a3
     JOIN axusergroupsdetail a4 ON a3.axusergroupsid = a4.axusergroupsid
     JOIN axuseraccess a5 ON a4.roles_id = a5.rname
     LEFT JOIN axuserlevelgroups a2 ON a2.usergroup = a3.groupname AND a2.usergroup <> 'default'
     LEFT JOIN tstructs t ON a5.sname = t.name AND t.blobno = 1::numeric
     LEFT JOIN iviews i ON a5.sname = i.name
     LEFT JOIN axpages p ON a5.sname = p.name AND p.pagetype = 'web'
     where (a5.stype in('i','t') or p.pagetype ='web')     
UNION ALL
SELECT DISTINCT a2.username,
    'default' AS groupname,
    'default' AS rname,
    t.name AS sname,
    't' AS stype,
    t.caption
   FROM tstructs t
     LEFT JOIN axuserlevelgroups a2 ON a2.usergroup = 'default'
  WHERE t.blobno = 1::numeric
UNION ALL
SELECT DISTINCT a2.username,
    'default' AS groupname,
    'default' AS rname,
    i.name AS sname,
    'i' AS stype,
    i.caption
   FROM iviews i
     LEFT JOIN axuserlevelgroups a2 ON a2.usergroup = 'default'
UNION ALL
SELECT DISTINCT a2.username,
    'default' AS groupname,
    'default' AS rname,
    p.name AS sname,
    'p' AS stype,
    p.caption
   FROM axpages p
     LEFT JOIN axuserlevelgroups a2 ON a2.usergroup = 'default'
  WHERE p.pagetype = 'web')a 
  where a.username = :puser$q1876$, $q1877$puser$q1877$, $q1878$puser~Character~$q1878$, $q1879$ALL$q1879$, NULL, $q1880$username,groupname,rname,sname,stype,caption$q1880$, $q1881$F$q1881$, $q1882$6 Hr$q1882$, NULL, NULL, NULL, $q1883$T$q1883$, $q1884$F$q1884$);
