INSERT INTO {schema}.axdirectsql (axdirectsqlid, cancel, sourceid, mapname, username, modifiedon, createdby, createdon, wkid, app_level, app_desc, app_slevel, cancelremarks, wfroles, sqlname, ddldatatype, sqlsrc, sqlsrccnd, sqltext, paramcal, sqlparams, accessstring, groupname, sqlquerycols, cachedata, cacheinterval, encryptedflds, adsdesc, smartlistcnd, pagination, applydimensions) VALUES ($q1917$99999999990023$q1917$, $q1918$F$q1918$, $q1919$0$q1919$, NULL, $q1920$admin$q1920$, $q1921$2026-01-30 00:00:00$q1921$, $q1922$admin$q1922$, $q1923$2026-01-30 00:00:00$q1923$, NULL, $q1924$1$q1924$, $q1925$1$q1925$, NULL, NULL, NULL, $q1926$axi_smartlist_ads_metadata$q1926$, NULL, $q1927$Internal$q1927$, $q1928$1$q1928$, $q1929$select
	a1.sqlname,
	a1.sqltext,
	a1.sqlparams,
	a1.sqlquerycols,
	a1.encryptedflds,
	a1.cachedata,
	a1.cacheinterval,
	b.fldname,
	b.fldcaption,
	b."normalized" ,
	b.sourcetable ,
	b.sourcefld ,
	hl.hyp_structtype,
	hl.hyp_transid,
	hl.tbl_hyperlink,hl.hyp_inline,
	case
		when lower(sqltext) like '%--axp_filter%' then 'T'
		else 'F'
	end as filters
from axdirectsql a1
join axpdef_smartlist a on a1.sqlname = a.adsname
join axpdef_smartlist_mdata b on a.axpdef_smartlistid =b.axpdef_smartlistid
left join(select axpdef_smartlistid,hfldname,hyp_structtype,hyp_transid, tbl_hyperlink,hyp_inline from axpdef_smartlist_hlink)hl
on hl.axpdef_smartlistid=a.axpdef_smartlistid and b.fldname = hl.hfldname
where a.adsname = :adsname
order by b.axpdef_smartlist_mdatarow $q1929$, $q1930$adsname$q1930$, $q1931$adsname~Character~$q1931$, $q1932$ALL$q1932$, NULL, NULL, $q1933$F$q1933$, $q1934$6 Hr$q1934$, NULL, NULL, NULL, NULL, NULL);
