INSERT INTO {schema}.axdirectsql (axdirectsqlid, cancel, sourceid, mapname, username, modifiedon, createdby, createdon, wkid, app_level, app_desc, app_slevel, cancelremarks, wfroles, sqlname, ddldatatype, sqlsrc, sqlsrccnd, sqltext, paramcal, sqlparams, accessstring, groupname, sqlquerycols, cachedata, cacheinterval, encryptedflds, adsdesc, smartlistcnd, pagination, applydimensions) VALUES ($q1953$1968550000010$q1953$, $q1954$F$q1954$, $q1955$0$q1955$, NULL, $q1956$admin$q1956$, $q1957$2026-07-14 12:33:10$q1957$, $q1958$admin$q1958$, $q1959$2026-06-19 00:00:00$q1959$, NULL, $q1960$1$q1960$, $q1961$1$q1961$, NULL, NULL, NULL, $q1962$DS_PendingApprovals$q1962$, NULL, $q1963$For developers$q1963$, $q1964$2$q1964$, $q1965$SELECT *
FROM vw_axpertinbox v
WHERE
    v.rectype = 'PEG'
    AND v.cstatus = 'Active'
    AND v.taskstatus = 'Pending'
    AND
    (
        COALESCE(TRIM(:uname),'') = ''
        OR v.touser = :uname
    )
    AND
    (
        COALESCE(TRIM(:searchtext), '') = ''
        OR
        LOWER
        (
            COALESCE(v.taskname,'') || ' ' ||
            COALESCE(v.taskid,'') || ' ' ||
            COALESCE(v.displaycontent,'') || ' ' ||
            COALESCE(v.displaytitle,'') || ' ' ||
            COALESCE(v.fromuser,'') || ' ' ||
            COALESCE(v.processname,'') || ' ' ||
            COALESCE(v.eventdatetime,'') || ' ' ||
            COALESCE(v.taskstatus,'')
        )
        LIKE LOWER('%' || TRIM(:searchtext) || '%')
    )
ORDER BY v.edatetime DESC
