INSERT INTO {schema}.axdirectsql (axdirectsqlid, cancel, sourceid, mapname, username, modifiedon, createdby, createdon, wkid, app_level, app_desc, app_slevel, cancelremarks, wfroles, sqlname, ddldatatype, sqlsrc, sqlsrccnd, sqltext, paramcal, sqlparams, accessstring, groupname, sqlquerycols, cachedata, cacheinterval, encryptedflds, adsdesc, smartlistcnd, pagination, applydimensions) VALUES ($q2517$99999999990028$q2517$, $q2518$F$q2518$, $q2519$0$q2519$, NULL, $q2520$admin$q2520$, $q2521$2025-12-23 13:22:07$q2521$, $q2522$admin$q2522$, $q2523$2025-12-19 16:06:57$q2523$, NULL, $q2524$1$q2524$, $q2525$1$q2525$, NULL, NULL, NULL, $q2526$axi_adscolumnlist$q2526$, NULL, $q2527$Internal$q2527$, $q2528$1$q2528$, $q2529$select b.fldcaption || '(' || b.fldname || ')' displaydata,
        b.fldname name,
        b.fldcaption caption,
        b.normalized,
        b.fdatatype,
        f.tablename sourcetable,
        f.fname sourcefld,
        CASE
            WHEN lower(sqltext) LIKE '%--axp_filter%'
            THEN 'T'
            ELSE 'F'
        END AS filters
   from axdirectsql a
   left join axpdef_smartlist c
          on a.sqlname = c.adsname
   left join axpdef_smartlist_mdata b
          on b.axpdef_smartlistid = c.axpdef_smartlistid
   left join axpflds f
          on b.srctransid = f.tstruct
         and b.srcfldname = f.fname
  where a.sqlname = :param1
    and b.hide = 'No'$q2529$, $q2530$param1$q2530$, $q2531$param1~Character~$q2531$, $q2532$ALL$q2532$, NULL, NULL, $q2533$F$q2533$, $q2534$6 Hr$q2534$, NULL, NULL, NULL, NULL, NULL);
