INSERT INTO {schema}.axdirectsql (axdirectsqlid, cancel, sourceid, mapname, username, modifiedon, createdby, createdon, wkid, app_level, app_desc, app_slevel, cancelremarks, wfroles, sqlname, ddldatatype, sqlsrc, sqlsrccnd, sqltext, paramcal, sqlparams, accessstring, groupname, sqlquerycols, cachedata, cacheinterval, encryptedflds, adsdesc, smartlistcnd, pagination, applydimensions) VALUES ($q2963$8887990000000$q2963$, $q2964$F$q2964$, $q2965$0$q2965$, NULL, $q2966$admin$q2966$, $q2967$2026-05-29 13:02:16$q2967$, $q2968$admin$q2968$, $q2969$2026-05-22 16:16:33$q2969$, NULL, $q2970$1$q2970$, $q2971$1$q2971$, NULL, NULL, NULL, $q2972$ds_smartlist_kpicharts$q2972$, NULL, $q2973$Internal$q2973$, $q2974$1$q2974$, $q2975$select b.kpicaption chartcaption,'KPI' charttype,null grpcol,kpi_aggfunc agg_func,kpi_aggcol agg_col,1 ord,b.axpdef_smartlist_kpirow ord2 from axpdef_smartlist a
join axpdef_smartlist_kpi b on a.axpdef_smartlistid = b.axpdef_smartlistid
where a.adsname = :adsname
union all
select b.chartcaption,b.charttype,b.chart_grpcol,chart_aggfun,chart_aggcol,2 ord,b.axpdef_smartlist_chartsrow from axpdef_smartlist a
