INSERT INTO {schema}.axdirectsql (axdirectsqlid, cancel, sourceid, mapname, username, modifiedon, createdby, createdon, wkid, app_level, app_desc, app_slevel, cancelremarks, wfroles, sqlname, ddldatatype, sqlsrc, sqlsrccnd, sqltext, paramcal, sqlparams, accessstring, groupname, sqlquerycols, cachedata, cacheinterval, encryptedflds, adsdesc, smartlistcnd, pagination, applydimensions) VALUES ($q2984$8881440000000$q2984$, $q2985$F$q2985$, $q2986$0$q2986$, NULL, $q2987$admin$q2987$, $q2988$2026-06-03 18:32:20$q2988$, $q2989$admin$q2989$, $q2990$2026-01-30 00:00:00$q2990$, NULL, $q2991$1$q2991$, $q2992$1$q2992$, NULL, NULL, NULL, $q2993$ds_smartlist_ads_metadata$q2993$, NULL, $q2994$Internal$q2994$, $q2995$1$q2995$, $q2996$select distinct a.sqlname,b.fldname,b.fldcaption,b.fdatatype, b."normalized" ,
f.tablename sourcetable ,b.srcfldname sourcefld ,hyp_structtype,hl.hyp_transid, REGEXP_REPLACE(hl.tbl_hyperlink, '^.*?\((.*?)\)', '\1')::text tbl_hyperlink,hl.hyp_inline,
case when smartlistcnd like '%Dynamic select columns%' then 'T' else 'F' end dynamiccolumns,
 coalesce(b.filter,'No') filters,
case when smartlistcnd like '%Pagination%' then 'T' else 'F' end pagination,
case when smartlistcnd like '%Sorting%' then 'T' else 'F' end sorting,b.srctransid ,b.srcfldname srcfld ,b.srcfldname,
b.axpdef_smartlist_mdatarow,b.hide hide
from axdirectsql a 
left join axpdef_smartlist c on a.sqlname = c.adsname
left join axpdef_smartlist_mdata b on b.axpdef_smartlistid =c.axpdef_smartlistid
left join axpflds f on b.srctransid = f.tstruct and b.srcfldname = f.fname
left join(select axpdef_smartlistid,hfldname,hyp_structtype,hyp_transid, tbl_hyperlink,hyp_inline from axpdef_smartlist_hlink)hl 
on hl.axpdef_smartlistid=c.axpdef_smartlistid and b.fldname = hl.hfldname
where sqlname = :adsname
order by b.axpdef_smartlist_mdatarow$q2996$, $q2997$adsname$q2997$, $q2998$adsname~Character~$q2998$, $q2999$ALL$q2999$, NULL, $q3000$sqlname,fldname,fldcaption,normalized,sourcetable,sourcefld,hyp_structtype,hyp_transid,tbl_hyperlink,hyp_inline,dynamiccolumns,filters,pagination,sorting$q3000$, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
