INSERT INTO {schema}.axp_cards (axp_cardsid, cancel, sourceid, mapname, username, modifiedon, createdby, createdon, wkid, app_level, app_desc, app_slevel, cancelremarks, wfroles, cardtypeui, cardtype, cardicon, charttype, sql_editor_cardsql, cardname, heightui, height, widthui, width, cachedata, autorefresh, orderno, clrpalet, trufalse, chartprops, accessstringui, chartjson, accessstring, axpfile_imgcard, con_name, pagecaption, axpfilepath_imgcard, pagename, cardbgclr, hcaption, isparentpage, htype, pagedesc, htranstypeui, htransid, is_migrated, html_editor_card, calendarsource, calendarstransid, dashboardcard, processcard, exp_editor_buttons, inchart, inhomepage, card_datasource, pluginname, indashboard) VALUES ($q4688$1784550000000$q4688$, $q4689$F$q4689$, $q4690$0$q4690$, $q4691$$q4691$, $q4692$admin$q4692$, $q4693$2026-02-28$q4693$, $q4694$admin$q4694$, $q4695$2024-12-28$q4695$, $q4696$$q4696$, $q4697$1$q4697$, $q4698$1$q4698$, $q4699$0$q4699$, $q4700$$q4700$, $q4701$$q4701$, $q4702$chart|Chart||,kpi|KPI||,list|List||,menu|Menu card||,modern menu|Modern menu||,image card|Image card||,calendar|Calendar||,html|HTML Card||$q4702$, $q4703$Custom plugin$q4703$, NULL, NULL, NULL, $q4704$News & Events$q4704$, $q4705$300$q4705$, $q4706$300px$q4706$, $q4707$30%$q4707$, $q4708$col-md-4$q4708$, $q4709$false$q4709$, $q4710$0$q4710$, $q4711$5$q4711$, NULL, NULL, NULL, $q4712$default$q4712$, $q4713${"attributes":{"cck":"","shwLgnd":,"xAxisL":"","yAxisL":"","gradClrChart":,"shwChartVal":,"threeD":"remove","enableSlick":,"numbSym":}}$q4713$, $q4714$,default,$q4714$, NULL, $q4715$agileerpdemoaxdef$q4715$, NULL, $q4716$E:DemobizAxpertWebagileerpdemoImageCard*$q4716$, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $q4717$$q4717$, $q4718$<div data-shadowdom="false" class="dasboard-cards">
    <div class="card">
        <div class="card-header">
            <h4 class="card-title mb-4">News & Events</h4>
            <div class="card-toolbar">
                <a href="#" data-bs-toggle="tooltip" class="border-bottom" onclick="LoadIframe('processflow.aspx?calendar=t');">
                    <span class="material-icons material-icons-style material-icons-2">
                        open_in_new
                    </span>
                </a>
            </div>
        </div>
        <div class="card-body">
          <div class="placeholder-content">
            <div class="placeholder-content_item"></div>
            <div class="placeholder-content_item"></div>
            <div class="placeholder-content_item"></div>
            <div class="placeholder-content_item"></div>
            <div class="placeholder-content_item"></div>
            <div class="placeholder-content_item"></div>
            <div class="placeholder-content_item"></div>
            <div class="placeholder-content_item"></div>
            <div class="placeholder-content_item"></div>
            <div class="placeholder-content_item"></div>
            <div class="placeholder-content_item"></div>
        </div>
            <div class="row" id="eventsContainer">
                <!-- Dynamic Events will be inserted here -->
            </div>
        </div>
    </div>

    <script>
        setTimeout(() => {
            var input = {
                name: "ds_homepage_events",
                sqlParams: {}
            };

            new EntityCommon().getDataFromDataSource(input, (result) => {
                var data = JSON.parse(JSON.parse(result).result.data[0].data_json);

                const container = document.getElementById('eventsContainer');

                // Function to calculate human-readable time difference
                function timeAgo(date) {
                    const now = new Date();
                    const eventDate = new Date(date);
                    const diffInSeconds = Math.floor((now - eventDate) / 1000);
                    const minutes = Math.floor(diffInSeconds / 60);
                    const hours = Math.floor(minutes / 60);
                    const days = Math.floor(hours / 24);
                    const weeks = Math.floor(days / 7);
                    const months = Math.floor(days / 30);

                    if (diffInSeconds < 60) return "Last updated just now";
                    if (minutes < 60) return `Last updated ${minutes} min${minutes > 1 ? "s" : ""} ago`;
                    if (hours < 24) return `Last updated ${hours} hour${hours > 1 ? "s" : ""} ago`;
                    if (days < 7) return `Last updated ${days} day${days > 1 ? "s" : ""} ago`;
                    if (weeks < 4) return `Last updated ${weeks} week${weeks > 1 ? "s" : ""} ago`;
                    return `Last updated ${months} month${months > 1 ? "s" : ""} ago`;
                }

                data.forEach(event => {
                    const card = document.createElement('div');
                    card.className = 'col-lg-12 Events-items';

                    card.innerHTML = `
                <div class="card">
                    <div class="row no-gutters align-items-center">
                        <div class="col-md-3">
                            <img class="card-img img-fluid" alt="Card image" src="${event.image}">
                        </div>
                        <div class="col-md-9">
                            <div class="card-body">
                                <h5 class="card-title">
                                    <a href="#" class="text-decoration-none" onclick="navigateToUrl('${event.link}')">${event.title}</a>
                                </h5>
                                <p class="card-text">${event.subtitle}</p>
                                <p class="card-text"><small class="text-muted">${timeAgo(event.time)}</small></p>
                            </div>
                        </div>
                    </div>
                </div>
            `;

                    container.appendChild(card);
                });
              
              $("#eventsContainer").parent().find(".placeholder-content").addClass("d-none");

            }, () => {
                //Error callback
            })

        }, 1)

    </script>
</div>$q4718$, $q4719$$q4719$, $q4720$$q4720$, NULL, NULL, $q4721$$q4721$, NULL, $q4722$T$q4722$, $q4723$ds_homepage_events$q4723$, $q4724$News Card$q4724$, $q4725$F$q4725$);
